    public static Decontare evalueazaDecontare(BigDecimal ramburs, BigDecimal virat, BigDecimal compensat,
            BigDecimal comision, String monedaRand, String monedaComanda) {
        BigDecimal v = virat == null ? BigDecimal.ZERO : virat;
        BigDecimal cp = compensat == null ? BigDecimal.ZERO : compensat;
        BigDecimal r = ramburs == null ? v.add(cp) : ramburs;
        BigDecimal d = r.subtract(v).subtract(cp).setScale(2, java.math.RoundingMode.HALF_UP);
        String mr = monedaRand == null ? "" : monedaRand.strip().toUpperCase(java.util.Locale.ROOT);
        String mc = monedaComanda == null ? "" : monedaComanda.strip().toUpperCase(java.util.Locale.ROOT);
        if (!mr.isEmpty() && !mc.isEmpty() && !mr.equals(mc))
            return new Decontare(C_MONEDA_DIFERITA, d);
        if (d.abs().compareTo(JUMATATE_BAN) <= 0)
            return new Decontare(cp.signum() > 0 ? C_COMPENSAT : "", d);
        if (d.signum() < 0)
            return new Decontare(C_SUPRAPLATA, d);
        if (comision == null)
            return new Decontare(C_DIFERENTA_NEEXPLICATA, d);
        return new Decontare(comision.subtract(d).abs().compareTo(prag("TOL_SUMA")) <= 0 ? C_COMISION_DEDUS
                : C_COMISION_NEPOTRIVIT, d);
    }

